.relay-board { width: 100%; height: 100%; padding: 33px 42px; overflow: hidden; border-radius: 18px; background: #16343e; border: 1px solid #57737a; color: #eef6eb; box-shadow: 0 22px 50px #0004; }
header span { color: #cbeca5; letter-spacing: .19em; font-size: 13px; font-weight: 650; }
h1 { font-family: Georgia, serif; font-size: 77px; margin: 4px 0 6px; font-weight: 500; letter-spacing: -.056em; }
p { font-size: 21px; margin: 0; color: #c4dad9; }
.plot { width: 100%; height: 212px; display: block; margin-top: 12px; overflow: visible; }
.plot text { font: 18px system-ui; }
.numbers text { font: 14px ui-monospace, monospace; }
footer { border-top: 1px solid #57737a; padding-top: 16px; color: #c4dad9; font-size: 15px; }
footer strong { color: #e7efc2; }

.lab { height: 100%; border-radius: 18px; background: #e9edaa; color: #243124; padding: 33px; border: 1px solid #eef4b9; box-shadow: 0 22px 50px #0003; }
.lab span { font-size: 12px; letter-spacing: .16em; font-weight: 750; }
h2 { font-family: Georgia, serif; font-size: 55px; font-weight: 500; line-height: 1; margin: 9px 0; letter-spacing: -.05em; }
p { font-size: 18px; line-height: 1.38; margin: 0 0 18px; }
label { display: block; font-weight: 700; }
label output { float: right; }
input { display: block; width: 100%; accent-color: #26493a; margin: 10px 0 16px; }
.meter { border: 1px solid #6e8162; border-radius: 6px; height: 15px; overflow: hidden; background: #d4d68f; }
.meter div { height: 100%; width: 0; background: #294f44; transition: width 180ms ease-out; }
.reading { margin: 9px 0 15px; }
.reading output { font-weight: 750; }
.lab-buttons { display: flex; gap: 8px; margin-bottom: 14px; }
button { color: #233125; background: #f3f4c9; border-color: #81906d; font-size: 16px; }
small { font-size: 14px; }
@media (prefers-reduced-motion: reduce) { .meter div { transition: none; } }

compositions.js:
const input = root.querySelector('input');
const rate = root.querySelector('[data-rate]');
const queue = root.querySelector('[data-queue]');
const fill = root.querySelector('[data-fill]');
const play = root.querySelector('[data-play]');
const options = { signal: lifecycle.signal };
let waiting = 0;
let timer;
const draw = () => { queue.value = waiting; fill.style.width = Math.min(100, waiting * 5) + '%'; };
const step = () => { waiting = Math.max(0, waiting + Number(input.value) - 5); draw(); };
const pause = () => { clearInterval(timer); timer = undefined; play.textContent = 'Run'; };
input.addEventListener('input', () => { rate.value = input.value; }, options);
root.querySelector('[data-step]').addEventListener('click', step, options);
root.querySelector('[data-reset]').addEventListener('click', () => { pause(); waiting = 0; draw(); }, options);
play.addEventListener('click', () => {
  if (timer) return pause();
  timer = setInterval(step, 450);
  play.textContent = 'Pause';
}, options);
lifecycle.onCleanup(pause);

